import { generateText, reviewText } from './gemini';
import { getData } from './store';

// Ready-made texts: generated by Gemini, imported from a link, or picked from free libraries

export interface FoundText {
  title: string;
  content: string;
  source?: string;
  notes?: string[];
}

export const LEVELS = ['A1', 'A2', 'B1', 'B2', 'C1'] as const;
export type Level = (typeof LEVELS)[number];

export const LENGTHS = { short: 90, medium: 170, long: 280 } as const;
export type Length = keyof typeof LENGTHS;

export const MAX_WOVEN_WORDS = 12;

/** Learning words, weakest first: the default picks for a generated text. */
export function learningWordsByWeakness(): { id: string; label: string; translation: string }[] {
  return Object.values(getData().words)
    .filter((w) => !w.deleted && w.status === 'learning')
    .sort((a, b) => (a.card?.stability ?? 0) - (b.card?.stability ?? 0))
    .map((w) => ({ id: w.id, label: w.article ? `${w.article} ${w.lemma}` : w.lemma, translation: (w.meanings.split(',')[0] || w.translation).trim() }));
}

export type GenStage = 'writing' | 'reviewing';

/** Writer drafts the text, then a stricter critic model corrects it. */
export async function generate(level: Level, topic: string, length: Length, words: string[], onStage?: (s: GenStage) => void): Promise<FoundText> {
  onStage?.('writing');
  const draft = await generateText(level, topic, LENGTHS[length], words);
  onStage?.('reviewing');
  try {
    const r = await reviewText(level, words, draft.title, draft.text);
    const real = r.changes.filter((c) => c.before.trim() !== c.after.trim());
    const notes = real.map((c) => `${c.before} → ${c.after}: ${c.reason}`);
    if (r.levelNote) notes.push(r.levelNote);
    const fixes = real.length;
    return {
      title: r.title || draft.title,
      content: r.text || draft.text,
      source: `Сгенерировано · ${level} · ${fixes ? `критик исправил ${fixes}` : 'критик: без ошибок'}`,
      notes,
    };
  } catch {
    // The text is still usable without the review
    return { title: draft.title, content: draft.text, source: `Сгенерировано · ${level} · без проверки критика` };
  }
}

// --- Import by link (Jina Reader returns the readable part of a page as Markdown) ---

function cleanMarkdown(md: string): string {
  const paragraphs = md
    .replace(/!\[[^\]]*\]\([^)]*\)/g, '') // images
    .replace(/\[\[\d+\]\]\([^)]*\)/g, '') // footnote refs
    .replace(/\[([^\]]*)\]\([^)]*\)/g, '$1') // links -> text
    .replace(/[*_`]{1,3}([^*_`]+)[*_`]{1,3}/g, '$1') // emphasis
    .split(/\n\s*\n/)
    .map((p) => p.replace(/^#+\s*/, '').replace(/\s+/g, ' ').trim())
    .filter((p) => {
      if (/^[|*+\-\d.\s]/.test(p) && !/[.!?]$/.test(p)) return false; // lists, tables, menus
      // Keep real prose: long enough and ending like a sentence
      return p.length >= 60 && /[.!?»“"…:)]$/.test(p);
    });
  return paragraphs.join('\n\n');
}

export async function importFromUrl(url: string): Promise<FoundText> {
  let u: URL;
  try {
    u = new URL(url.trim());
  } catch {
    throw new Error('Это не похоже на ссылку');
  }
  const r = await fetch(`https://r.jina.ai/${u.href}`, { headers: { 'X-Retain-Images': 'none' } });
  if (r.status === 429) throw new Error('Сервис чтения ссылок занят — попробуй через минуту');
  if (!r.ok) throw new Error(`Не удалось открыть страницу (ошибка ${r.status})`);
  const raw = await r.text();
  const title = raw.match(/^Title:\s*(.+)$/m)?.[1]?.trim() || u.hostname;
  const body = raw.split(/^Markdown Content:\s*$/m)[1] ?? raw;
  const content = cleanMarkdown(body);
  if (content.length < 100) throw new Error('Не нашёл на странице связного текста. Скопируй текст и вставь вручную.');
  return { title, content, source: u.hostname.replace(/^www\./, '') };
}

// --- MediaWiki sites with free licenses (all answer CORS requests with origin=*) ---

export interface Wiki {
  name: string;
  api: string;
  license: string; // shown as the text's source (attribution)
}

export const KLEXIKON: Wiki = { name: 'Klexikon', api: 'https://klexikon.zum.de/api.php', license: 'CC BY-SA' };
export const MINIKLEXIKON: Wiki = { name: 'MiniKlexikon', api: 'https://miniklexikon.zum.de/api.php', license: 'CC BY-SA 4.0' };
export const WIKINEWS: Wiki = { name: 'Wikinews', api: 'https://de.wikinews.org/w/api.php', license: 'CC BY 2.5' };

async function wiki(w: Wiki, params: Record<string, string>) {
  const q = new URLSearchParams({ ...params, format: 'json', formatversion: '2', origin: '*' });
  const r = await fetch(`${w.api}?${q}`);
  if (!r.ok) throw new Error(`${w.name} не отвечает (ошибка ${r.status})`);
  return r.json();
}

export async function wikiRandom(w: Wiki, n = 12): Promise<string[]> {
  const j = await wiki(w, { action: 'query', list: 'random', rnnamespace: '0', rnlimit: String(n) });
  return j.query.random.map((p: { title: string }) => p.title);
}

export async function wikiSearch(w: Wiki, term: string): Promise<string[]> {
  const j = await wiki(w, { action: 'query', list: 'search', srsearch: term, srnamespace: '0', srlimit: '15' });
  return j.query.search.map((p: { title: string }) => p.title);
}

export async function wikiArticle(w: Wiki, title: string): Promise<FoundText> {
  const j = await wiki(w, { action: 'parse', page: title, redirects: '1', prop: 'text' });
  if (!j.parse?.text) throw new Error(`${w.name}: не удалось открыть «${title}»`);
  const doc = new DOMParser().parseFromString(j.parse.text, 'text/html');
  // Status boxes, infoboxes, captions and navigation are not part of the article
  doc.querySelectorAll('table, figure, .navbox, .thumb, style, script, sup.reference').forEach((n) => n.remove());
  // MiniKlexikon articles are short: keep shorter paragraphs there
  const min = w === MINIKLEXIKON ? 15 : 40;
  const clean = (s: string | null) => (s ?? '').replace(/\[\d+\]/g, '').replace(/\s+/g, ' ').trim();
  const pick = (nodes: Element[]) => nodes.map((p) => clean(p.textContent)).filter((p) => p.length > min);
  // Top-level paragraphs first; some pages (and some browsers' parsing) nest them deeper
  let paras = pick([...doc.querySelectorAll('.mw-parser-output > p')]);
  if (!paras.length) paras = pick([...doc.querySelectorAll('p')]);
  if (!paras.length)
    paras = (doc.body.textContent ?? '')
      .split(/\n+/)
      .map(clean)
      .filter((p) => p.length > min && /[.!?»“"]$/.test(p));
  if (!paras.length) throw new Error(`В статье «${title}» нет связного текста — выбери другую`);
  return { title: j.parse.title, content: paras.join('\n\n'), source: `${w.name} · ${w.license}` };
}

// --- Grimm fairy tales (public domain), bundled with the app ---

export interface Tale {
  title: string;
  text: string;
}

let tales: Tale[] | null = null;

export async function grimmTales(): Promise<Tale[]> {
  if (tales) return tales;
  const r = await fetch(`${import.meta.env.BASE_URL}library/grimm.json`);
  if (!r.ok) throw new Error('Не удалось загрузить сказки');
  tales = (await r.json()) as Tale[];
  return tales;
}

/** Rough reading time at a learner's pace (~80 words a minute). */
export const readingMinutes = (text: string) => Math.max(1, Math.round(text.split(/\s+/).length / 80));
